import unittest
from io import BytesIO
from xml.etree import ElementTree
from zipfile import ZipFile

from xlsxwriter.workbook import Workbook


class TestTableHeaders(unittest.TestCase):
    """Test uniqueness of custom and generated table column headers."""

    def test_default_header_collisions(self):
        """Reject duplicate headers when one name is generated by default."""
        column_options = [
            [{"header": "Column2"}, {}],
            [{}, {"header": "Column1"}],
            [{"header": "column2"}],
            [{}, {"header": "COLUMN1"}],
        ]

        for columns in column_options:
            with self.subTest(columns=columns):
                output = BytesIO()
                with Workbook(output) as workbook:
                    worksheet = workbook.add_worksheet()
                    with self.assertWarnsRegex(UserWarning, "Duplicate header name"):
                        result = worksheet.add_table("A1:B3", {"columns": columns})
                    self.assertEqual(result, -2)

                with ZipFile(output) as archive:
                    self.assertNotIn("xl/tables/table1.xml", archive.namelist())

    def test_default_header_collision_without_header_row(self):
        """Table column names must be unique even without a visible header row."""
        output = BytesIO()
        with Workbook(output) as workbook:
            worksheet = workbook.add_worksheet()
            with self.assertWarnsRegex(UserWarning, "Duplicate header name"):
                result = worksheet.add_table(
                    "A1:B3",
                    {"header_row": False, "columns": [{}, {"header": "Column1"}]},
                )
            self.assertEqual(result, -2)

        with ZipFile(output) as archive:
            self.assertNotIn("xl/tables/table1.xml", archive.namelist())

    def test_explicit_header_collisions(self):
        """Continue to reject explicitly duplicated case-insensitive headers."""
        output = BytesIO()
        with Workbook(output) as workbook:
            worksheet = workbook.add_worksheet()
            with self.assertWarnsRegex(UserWarning, "Duplicate header name"):
                result = worksheet.add_table(
                    "A1:B3", {"columns": [{"header": "Label"}, {"header": "label"}]}
                )
            self.assertEqual(result, -2)

        with ZipFile(output) as archive:
            self.assertNotIn("xl/tables/table1.xml", archive.namelist())

    def test_duplicate_headers_preserve_existing_total_cells(self):
        """Reject duplicate names before writing the current column's total."""
        for total in ({"total_string": "Changed"}, {"total_function": "sum"}):
            with self.subTest(total=total):
                output = BytesIO()
                with Workbook(output) as workbook:
                    worksheet = workbook.add_worksheet()
                    worksheet.write("B3", "Existing value")
                    with self.assertWarnsRegex(UserWarning, "Duplicate header name"):
                        result = worksheet.add_table(
                            "A1:B3",
                            {
                                "total_row": True,
                                "columns": [
                                    {"header": "Label"},
                                    {"header": "label", **total},
                                ],
                            },
                        )
                    self.assertEqual(result, -2)

                with ZipFile(output) as archive:
                    ns = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
                    sheet = ElementTree.fromstring(
                        archive.read("xl/worksheets/sheet1.xml")
                    )
                    cell = sheet.find(f".//{ns}c[@r='B3']")
                    self.assertEqual(cell.attrib["t"], "s")
                    self.assertIsNone(cell.find(f"{ns}f"))
                    strings = ElementTree.fromstring(
                        archive.read("xl/sharedStrings.xml")
                    )
                    value = strings[int(cell.findtext(f"{ns}v"))].findtext(f"{ns}t")
                self.assertEqual(value, "Existing value")

    def test_unique_default_headers(self):
        """Preserve valid combinations of explicit and generated headers."""
        cases = [
            ([], ["Column1", "Column2"]),
            ([{"header": "Product"}, {}], ["Product", "Column2"]),
            ([{}, {"header": "Product"}], ["Column1", "Product"]),
            ([{"header": "Product"}], ["Product", "Column2"]),
        ]

        for columns, expected in cases:
            with self.subTest(columns=columns):
                output = BytesIO()
                with Workbook(output) as workbook:
                    worksheet = workbook.add_worksheet()
                    result = worksheet.add_table("A1:B3", {"columns": columns})
                    self.assertEqual(result, 0)

                with ZipFile(output) as archive:
                    table = ElementTree.fromstring(archive.read("xl/tables/table1.xml"))
                    ns = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
                    headers = [
                        column.attrib["name"]
                        for column in table.findall(f"{ns}tableColumns/{ns}tableColumn")
                    ]
                self.assertEqual(headers, expected)
